{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { DatabaseSync } from 'node:sqlite';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = dirname(fileURLToPath(import.meta.url));
const database = new DatabaseSync(process.env.DB_PATH || join(root, 'workboard.sqlite'));
database.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL
  )
  ;
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0,
    priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))
  )
`);
database.exec('PRAGMA foreign_keys = ON');
try { database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0'); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
try { database.exec("ALTER TABLE projects ADD COLUMN default_task_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_task_priority IN ('Low', 'Normal', 'High'))"); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
try { database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))"); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
try { database.exec('ALTER TABLE tasks ADD COLUMN due_date TEXT'); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
try { database.exec("ALTER TABLE tasks ADD COLUMN notes TEXT NOT NULL DEFAULT ''"); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
try { database.exec('ALTER TABLE tasks ADD COLUMN deleted INTEGER NOT NULL DEFAULT 0'); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
try { database.exec('ALTER TABLE tasks ADD COLUMN sort_order INTEGER'); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
database.exec('UPDATE tasks SET sort_order = id WHERE sort_order IS NULL');
database.exec(`
  CREATE TABLE IF NOT EXISTS task_project_positions (
    task_id INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    sort_order INTEGER NOT NULL,
    PRIMARY KEY (task_id, project_id)
  );
  INSERT OR IGNORE INTO task_project_positions (task_id, project_id, sort_order)
    SELECT id, project_id, sort_order FROM tasks;
`);

const listProjects = database.prepare(`SELECT p.id, p.name, p.archived, p.default_task_priority AS defaultTaskPriority,
  (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id AND t.completed = 1 AND t.deleted = 0) AS completedCount,
  (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id AND t.deleted = 0) AS totalCount
  FROM projects p ORDER BY p.id`);
const findProject = database.prepare(`SELECT p.id, p.name, p.archived, p.default_task_priority AS defaultTaskPriority,
  (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id AND t.completed = 1 AND t.deleted = 0) AS completedCount,
  (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id AND t.deleted = 0) AS totalCount
  FROM projects p WHERE p.id = ?`);
const createProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
const importProject = database.prepare('INSERT INTO projects (name, archived, default_task_priority) VALUES (?, ?, ?)');
const importTask = database.prepare('INSERT INTO tasks (project_id, title, completed, priority, due_date, notes, deleted, sort_order) VALUES (?, ?, ?, ?, ?, ?, ?, ?)');
const listTasks = database.prepare("SELECT id, project_id AS projectId, title, completed, priority, due_date AS dueDate, notes, deleted FROM tasks WHERE project_id = ? ORDER BY sort_order, id");
const createTask = database.prepare('INSERT INTO tasks (project_id, title, priority, sort_order) VALUES (?, ?, ?, COALESCE((SELECT MAX(sort_order) + 1 FROM task_project_positions WHERE project_id = ?), 0))');
const createTaskPosition = database.prepare('INSERT INTO task_project_positions (task_id, project_id, sort_order) VALUES (?, ?, ?)');
const positionForProject = database.prepare('SELECT sort_order AS sortOrder FROM task_project_positions WHERE task_id = ? AND project_id = ?');
const nextProjectPosition = database.prepare('SELECT COALESCE(MAX(sort_order) + 1, 0) AS sortOrder FROM task_project_positions WHERE project_id = ?');
const rememberTaskPosition = database.prepare('INSERT OR IGNORE INTO task_project_positions (task_id, project_id, sort_order) VALUES (?, ?, ?)');
const moveTask = database.prepare('UPDATE tasks SET project_id = ?, sort_order = ? WHERE id = ? AND project_id = ?');
const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');
const renameTask = database.prepare('UPDATE tasks SET title = ? WHERE id = ? AND project_id = ?');
const updatePriority = database.prepare("UPDATE tasks SET priority = ? WHERE id = ? AND project_id = ?");
const updateDueDate = database.prepare('UPDATE tasks SET due_date = ? WHERE id = ? AND project_id = ?');
const updateNotes = database.prepare('UPDATE tasks SET notes = ? WHERE id = ? AND project_id = ?');
const updateDeleted = database.prepare('UPDATE tasks SET deleted = ? WHERE id = ? AND project_id = ?');
const updateArchive = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = database.prepare('UPDATE projects SET name = ? WHERE id = ? AND archived = 0');
const updateDefaultPriority = database.prepare("UPDATE projects SET default_task_priority = ? WHERE id = ? AND archived = 0");

function sendJson(response, status, body) {
  response.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(body));
}

function isValidDate(value) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!match) return false;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  if (year < 1 || month < 1 || month > 12) return false;
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day >= 1 && day <= days[month - 1];
}

function validateProjectDocument(document) {
  const priorities = ['Low', 'Normal', 'High'];
  if (!document || typeof document !== 'object' || Array.isArray(document) ||
      document.format !== 'workboard-project' || document.version !== 1 ||
      !document.project || typeof document.project !== 'object' || Array.isArray(document.project)) return false;
  const project = document.project;
  if (typeof project.name !== 'string' || !project.name.trim() || typeof project.archived !== 'boolean' ||
      !priorities.includes(project.defaultPriority) || !Array.isArray(project.tasks)) return false;
  return project.tasks.every(task => task && typeof task === 'object' && !Array.isArray(task) &&
    typeof task.title === 'string' && !!task.title.trim() && typeof task.completed === 'boolean' &&
    priorities.includes(task.priority) && typeof task.dueDate === 'string' &&
    (task.dueDate === '' || isValidDate(task.dueDate)) && typeof task.notes === 'string' &&
    typeof task.deleted === 'boolean');
}

async function sendFile(response, filename, contentType) {
  try {
    const content = await readFile(join(root, filename));
    response.writeHead(200, { 'content-type': contentType });
    response.end(content);
  } catch {
    response.writeHead(500);
    response.end('Unable to load application');
  }
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, 'http://localhost');
  if (request.method === 'GET' && url.pathname === '/health') {
    return sendJson(response, 200, { status: 'ok' });
  }
  if (request.method === 'GET' && url.pathname === '/api/projects') {
    return sendJson(response, 200, listProjects.all().map(project => ({ ...project, archived: Boolean(project.archived) })));
  }
  if (request.method === 'POST' && url.pathname === '/api/projects') {
    let body = '';
    for await (const chunk of request) body += chunk;
    let name;
    try {
      name = JSON.parse(body).name;
    } catch {
      return sendJson(response, 400, { error: 'Invalid request' });
    }
    if (typeof name !== 'string' || !name.trim()) {
      return sendJson(response, 400, { error: 'Project name is required' });
    }
    const trimmedName = name.trim();
    const result = createProject.run(trimmedName);
    return sendJson(response, 201, { id: Number(result.lastInsertRowid), name: trimmedName });
  }
  if (request.method === 'POST' && url.pathname === '/api/import') {
    let body;
    try { body = await readRequestJson(request); } catch { return sendJson(response, 400, { error: 'Invalid project JSON' }); }
    if (!body || typeof body !== 'object' || typeof body.name !== 'string' || !body.name.trim()) return sendJson(response, 400, { error: 'Project name is required' });
    let document;
    try { document = JSON.parse(body.document); } catch { return sendJson(response, 400, { error: 'Invalid project JSON' }); }
    if (!validateProjectDocument(document)) return sendJson(response, 400, { error: 'Invalid project JSON' });
    let projectId;
    database.exec('BEGIN IMMEDIATE');
    try {
      const projectResult = importProject.run(body.name.trim(), document.project.archived ? 1 : 0, document.project.defaultPriority);
      projectId = Number(projectResult.lastInsertRowid);
      document.project.tasks.forEach((task, index) => {
        const taskResult = importTask.run(projectId, task.title, task.completed ? 1 : 0, task.priority, task.dueDate || null, task.notes.replace(/\r\n?/g, '\n'), task.deleted ? 1 : 0, index);
        createTaskPosition.run(Number(taskResult.lastInsertRowid), projectId, index);
      });
      database.exec('COMMIT');
    } catch (error) {
      database.exec('ROLLBACK');
      throw error;
    }
    return sendJson(response, 201, { id: projectId });
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (request.method === 'PATCH' && projectMatch) {
    let body;
    try { body = await readRequestJson(request); } catch { return sendJson(response, 400, { error: 'Invalid request' }); }
    if (typeof body.name === 'string') {
      if (!body.name.trim()) return sendJson(response, 400, { error: 'Project name is required' });
      const result = renameProject.run(body.name.trim(), Number(projectMatch[1]));
      return result.changes ? sendJson(response, 200, { ok: true }) : sendJson(response, 404, { error: 'Active project not found' });
    }
    if (typeof body.defaultTaskPriority === 'string') {
      if (!['Low', 'Normal', 'High'].includes(body.defaultTaskPriority)) return sendJson(response, 400, { error: 'Invalid default task priority' });
      const result = updateDefaultPriority.run(body.defaultTaskPriority, Number(projectMatch[1]));
      return result.changes ? sendJson(response, 200, { ok: true }) : sendJson(response, 404, { error: 'Active project not found' });
    }
    if (typeof body.archived !== 'boolean') return sendJson(response, 400, { error: 'Invalid archive state' });
    const result = updateArchive.run(body.archived ? 1 : 0, Number(projectMatch[1]));
    return result.changes ? sendJson(response, 200, { ok: true }) : sendJson(response, 404, { error: 'Project not found' });
  }
  if (request.method === 'GET' && projectMatch) {
    const project = findProject.get(Number(projectMatch[1]));
    return project ? sendJson(response, 200, { ...project, archived: Boolean(project.archived) }) : sendJson(response, 404, { error: 'Project not found' });
  }
  const exportMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/export$/);
  if (request.method === 'GET' && exportMatch) {
    const project = findProject.get(Number(exportMatch[1]));
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    const tasks = listTasks.all(Number(exportMatch[1])).map(task => ({
      title: task.title,
      completed: Boolean(task.completed),
      priority: task.priority || 'Normal',
      dueDate: task.dueDate || '',
      notes: (task.notes || '').replace(/\r\n?/g, '\n'),
      deleted: Boolean(task.deleted),
    }));
    const document = {
      format: 'workboard-project',
      version: 1,
      project: {
        name: project.name,
        archived: Boolean(project.archived),
        defaultPriority: project.defaultTaskPriority || 'Normal',
        tasks,
      },
    };
    response.writeHead(200, {
      'content-type': 'application/json; charset=utf-8',
      'content-disposition': 'attachment; filename="workboard-project.json"',
    });
    return response.end(JSON.stringify(document));
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksMatch) {
    const projectId = Number(tasksMatch[1]);
    if (!findProject.get(projectId)) return sendJson(response, 404, { error: 'Project not found' });
    if (request.method === 'GET') return sendJson(response, 200, listTasks.all(projectId).map(task => ({ ...task, completed: Boolean(task.completed), deleted: Boolean(task.deleted) })));
    if (request.method === 'POST') {
      let body;
      try { body = await readRequestJson(request); } catch { return sendJson(response, 400, { error: 'Invalid request' }); }
      if (typeof body.title !== 'string' || !body.title.trim()) return sendJson(response, 400, { error: 'Task title is required' });
      const title = body.title.trim();
      const priority = findProject.get(projectId).defaultTaskPriority;
      const result = createTask.run(projectId, title, priority, projectId);
      const taskId = Number(result.lastInsertRowid);
      const sortOrder = database.prepare('SELECT sort_order AS sortOrder FROM tasks WHERE id = ?').get(taskId).sortOrder;
      createTaskPosition.run(taskId, projectId, sortOrder);
      return sendJson(response, 201, { id: taskId, projectId, title, completed: false, priority });
    }
  }
  const taskMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);
  const moveMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)\/move$/);
  if (request.method === 'POST' && moveMatch) {
    const sourceId = Number(moveMatch[1]);
    const taskId = Number(moveMatch[2]);
    let body;
    try { body = await readRequestJson(request); } catch { return sendJson(response, 400, { error: 'Invalid request' }); }
    const source = findProject.get(sourceId);
    const destinationId = Number(body.destinationProjectId);
    const destination = findProject.get(destinationId);
    if (!source || source.archived || !destination || destination.archived || sourceId === destinationId) {
      return sendJson(response, 400, { error: 'Invalid destination project' });
    }
    const sourceTask = database.prepare('SELECT id FROM tasks WHERE id = ? AND project_id = ?').get(taskId, sourceId);
    if (!sourceTask) return sendJson(response, 404, { error: 'Task not found' });
    const existingPosition = positionForProject.get(taskId, destinationId);
    const destinationPosition = existingPosition?.sortOrder ?? nextProjectPosition.get(destinationId).sortOrder;
    rememberTaskPosition.run(taskId, destinationId, destinationPosition);
const app = document.querySelector('#app');

function element(tag, text, attributes = {}) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  for (const [name, value] of Object.entries(attributes)) node.setAttribute(name, value);
  return node;
}

function normalizeSearchQuery(value) {
  return normalizeSearchText(value.trim());
}

function normalizeSearchText(value) {
  return value.replace(/[ \t]+/g, ' ').replace(/[A-Z]/g, letter => letter.toLowerCase());
}

async function loadProjects() {
  const response = await fetch('/api/projects');
  if (!response.ok) throw new Error('Could not load projects');
  return response.json();
}

function projectRow(project, refresh) {
  const row = element('div', undefined, { 'data-testid': 'project-row', class: 'project-row' });
  row.append(element('span', project.name, { class: 'project-name' }));
  row.append(element('span', `${project.completedCount}/${project.totalCount} completed`, { 'data-testid': 'project-summary' }));
  const open = element('button', 'Open project', { type: 'button' });
  open.addEventListener('click', () => {
    history.pushState({}, '', `/projects/${project.id}`);
    renderProject(project.id);
  });
  row.append(open);
  if (project.archived) {
    const restore = element('button', 'Restore project', { type: 'button' });
    restore.addEventListener('click', async () => {
      await fetch(`/api/projects/${project.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ archived: false }) });
      refresh();
    });
    row.append(restore);
  } else {
    const archive = element('button', 'Archive project', { type: 'button' });
    archive.addEventListener('click', async () => {
      await fetch(`/api/projects/${project.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ archived: true }) });
      refresh();
    });
    row.append(archive);
  }
  return row;
}

async function renderList() {
  app.replaceChildren();
  app.append(element('h1', 'Workboard'));

  const form = element('form');
  const input = element('input', undefined, { type: 'text', 'aria-label': 'Project name', autocomplete: 'off' });
  const submit = element('button', 'Create project', { type: 'submit' });
  form.append(input, submit);
  const alert = element('p', '', { id: 'alert', role: 'alert', hidden: '' });
  const projects = element('section', undefined, { id: 'projects', 'aria-label': 'Projects' });
  const importForm = element('form');
  const importJson = element('textarea', undefined, { 'aria-label': 'Project JSON', rows: '8' });
  const importName = element('input', undefined, { type: 'text', 'aria-label': 'Imported project name', autocomplete: 'off' });
  const importButton = element('button', 'Import project', { type: 'submit' });
  importForm.append(importJson, importName, importButton);
  const importAlert = element('p', '', { role: 'alert', hidden: '' });
  importForm.addEventListener('submit', async event => {
    event.preventDefault();
    if (!importName.value.trim()) {
      importAlert.textContent = 'Project name is required';
      importAlert.hidden = false;
      return;
    }
    const result = await fetch('/api/import', {
      method: 'POST', headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ document: importJson.value, name: importName.value }),
    });
    if (!result.ok) {
      const error = await result.json();
      importAlert.textContent = error.error === 'Project name is required' ? error.error : 'Invalid project JSON';
      importAlert.hidden = false;
      return;
    }
    const imported = await result.json();
    history.pushState({}, '', `/projects/${imported.id}`);
    renderProject(imported.id);
  });
  const filter = element('select', undefined, { 'aria-label': 'Project filter' });
  filter.append(element('option', 'Active', { value: 'active' }), element('option', 'Archived', { value: 'archived' }));
